31	#[derive(Clone, Copy, Eq, PartialEq, Hash, DebugWithContext)]
32	enum ValueNumber {
33	    // Top of the lattice = Don't know = uninitialized
34	    Top,
35	    // Belongs to a congruence class represented by the inner value.
36	    Number(Value),
37	}
