140	/// Convert a PHI argument to Expr
141	fn phi_to_expr(context: &Context, vntable: &VNTable, phi_arg: Value) -> Expr {
142	    let phi_arg = phi_arg.get_argument(context).unwrap();
143	    let phi_args = phi_arg
144	        .block
145	        .pred_iter(context)
146	        .map(|pred| {
147	            let incoming_val = phi_arg
148	                .get_val_coming_from(context, pred)
149	                .expect("No parameter from predecessor");
150	            vntable.value_map.get(&incoming_val).cloned().unwrap()
151	        })
152	        .collect();
153	    Expr::Phi(phi_args)
154	}
